CREATE COLUMN TABLE "TEST_AP"."OBMI" ("ID" INTEGER CS_INT NOT NULL , "IndexType" INTEGER CS_INT DEFAULT -1 NOT NULL , "Code" NVARCHAR(10) NOT NULL , "Descr" NVARCHAR(254), "RefIndCod1" NVARCHAR(10), "RefIndCod2" NVARCHAR(10), "RefIndCod3" NVARCHAR(10), "UserSign" SMALLINT CS_INT, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBMI_IND_CODE_K" ON "TEST_AP"."OBMI" ( "IndexType" ASC, "Code" ASC )